// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.classifierimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.CompoundExecutorimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.intent.IntentClassificationimport com.roshan.persona.brain.intent.calibration.ConfidenceCalibratorimport com.roshan.persona.brain.intent.compound.CompoundIntentDetectorimport com.roshan.persona.brain.intent.context.ContextualPreProcessorimport com.roshan.persona.brain.intent.slots.NerModelInterfaceimport com.roshan.persona.brain.intent.slots.SlotFillerimport com.roshan.persona.common.CorrelationIdimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 0: Intent Classifier. * * 5-stage pipeline: *   1. Regex Match (0.1ms, 50% of intents) *   2. Keyword + Token Match (0.5ms, +25%) *   3. Embedding Similarity (5-25ms, +8%) *   4. Slot Filler (regex + NER, 0-15ms) *   5. Confidence Calibration + Compound Detection (final gate) * * @see <a href="docs/spec/module2-spec-review.pdf">§4 Layer 0</a> */@Singletonclass IntentClassifier @Inject constructor(    private val regexMatcher: RegexIntentMatcher = RegexIntentMatcher(),    private val keywordMatcher: KeywordIntentMatcher = KeywordIntentMatcher(),    private val embeddingMatcher: EmbeddingIntentMatcher,    private val slotFiller: SlotFiller,    private val compoundDetector: CompoundIntentDetector = CompoundIntentDetector(),    private val contextualPreProcessor: ContextualPreProcessor = ContextualPreProcessor(),) {    /**     * Classify [rawInput] into an [IntentClassification].     *     * Pipeline:     *   1. Apply contextual override (if pending expectation)     *   2. Try regex match → if hit, calibrate + return     *   3. Try keyword match → if hit, calibrate + return     *   4. Try embedding match → if hit, calibrate + return     *   5. If no match, check for compound intent     *   6. If still no match, return Unknown     *     * Slot filling runs after intent is detected (Stage 4).     */    suspend fun classify(        rawInput: String,        context: BrainContext,    ): IntentClassification {        val correlationId = context.correlationId        val startNanos = System.nanoTime()        // Stage 0: Contextual override (coreference resolution)        val input = contextualPreProcessor.applyContext(rawInput, context)        if (input != rawInput) {            Timber.tag("NOUS.L0").v("Contextual override applied: '%s' → '%s'", rawInput, input)        }        // Try each matcher in order. First hit wins.        var matchedIntent: Intent? = null        var extractor: com.roshan.persona.brain.intent.ExtractorType? = null        var rawScore: Float = 0f        // Stage 1: Regex        val regexMatch = regexMatcher.match(input)        if (regexMatch != null) {            matchedIntent = regexMatch.intent            extractor = com.roshan.persona.brain.intent.ExtractorType.REGEX            rawScore = 1.0f  // regex match = full confidence pre-calibration            Timber.tag("NOUS.L0").v("Stage 1 (regex) hit: %s", regexMatch.intentType.simpleName)        }        // Stage 2: Keyword (if regex missed)        if (matchedIntent == null) {            val keywordMatch = keywordMatcher.match(input)            if (keywordMatch != null) {                matchedIntent = keywordMatch.intent                extractor = com.roshan.persona.brain.intent.ExtractorType.KEYWORD                rawScore = keywordMatch.rawScore.coerceIn(0f, 1f)                Timber.tag("NOUS.L0").v("Stage 2 (keyword) hit: %s (score=%.2f)", keywordMatch.intentType.simpleName, rawScore)            }        }        // Stage 3: Embedding (if keyword missed)        if (matchedIntent == null) {            val embeddingMatch = embeddingMatcher.match(input)            if (embeddingMatch != null) {                matchedIntent = embeddingMatch.intent                extractor = com.roshan.persona.brain.intent.ExtractorType.EMBEDDING                rawScore = embeddingMatch.rawSimilarity                Timber.tag("NOUS.L0").v("Stage 3 (embedding) hit: %s (sim=%.2f)", embeddingMatch.intentType.simpleName, rawScore)            }        }        // Stage 5a: Compound detection (if no single-intent match)        var isCompound = false        if (matchedIntent == null) {            val compound = compoundDetector.detect(input) { subUtterance ->                // Re-run Stage 1-3 on each sub-utterance                regexMatcher.match(subUtterance)?.intent                    ?: keywordMatcher.match(subUtterance)?.intent                    ?: embeddingMatcher.match(subUtterance)?.intent            }            if (compound != null) {                matchedIntent = compound                extractor = com.roshan.persona.brain.intent.ExtractorType.COMPOSITE                rawScore = 0.9f  // compound detection is high-confidence                isCompound = true                Timber.tag("NOUS.L0").v("Stage 5 (compound) detected: %d intents", compound.intents.size)            }        }        // No match at all → Unknown        if (matchedIntent == null || extractor == null) {            Timber.tag("NOUS.L0").v("No intent matched → Unknown")            return IntentClassification(                intent = Intent.Unknown(raw = input),                confidence = 0f,                extractor = com.roshan.persona.brain.intent.ExtractorType.EMBEDDING,                extractedSlots = emptyMap(),                durationNanos = System.nanoTime() - startNanos,                correlationId = correlationId,                usedNer = false,                isCompound = false,            )        }        // Stage 4: Slot filling (skip for compound — sub-intents already filled)        var finalIntent = matchedIntent        var usedNer = false        if (matchedIntent !is Intent.Compound) {            val beforeSlots = countNullSlots(matchedIntent)            finalIntent = slotFiller.fillSlots(input, matchedIntent)            val afterSlots = countNullSlots(finalIntent)            usedNer = afterSlots < beforeSlots  // NER filled something        }        // Stage 5b: Confidence calibration (Platt scaling)        // At this point `extractor` is guaranteed non-null (the null-check        // above returned early at line 123), so we can safely use `!!` —        // but to be defensive we use an explicit null check that returns        // a proper Unknown classification if the invariant ever breaks.        val safeExtractor = extractor            ?: return IntentClassification(                intent = Intent.Unknown(raw = input),                confidence = 0f,                extractor = com.roshan.persona.brain.intent.ExtractorType.EMBEDDING,                extractedSlots = emptyMap(),                durationNanos = System.nanoTime() - startNanos,                correlationId = correlationId,                usedNer = false,                isCompound = false,            )        val calibratedConfidence = ConfidenceCalibrator.calibrate(rawScore, safeExtractor)        val durationNanos = System.nanoTime() - startNanos        Timber.tag("NOUS.L0").v(            "Classified: %s (extractor=%s, raw=%.2f, calibrated=%.2f, ner=%s, compound=%s, %dms)",            finalIntent?.let { it::class.simpleName } ?: "Unknown",            extractor,            rawScore,            calibratedConfidence,            usedNer,            isCompound,            durationNanos / 1_000_000,        )        return IntentClassification(            intent = finalIntent,            confidence = calibratedConfidence,            extractor = extractor,            extractedSlots = emptyMap(),  // slots are inside the intent            durationNanos = durationNanos,            correlationId = correlationId,            usedNer = usedNer,            isCompound = isCompound,        )    }    /** Count how many slots are null in the intent (used to detect NER effect). */    private fun countNullSlots(intent: Intent): Int = when (intent) {        is Intent.Call -> if (intent.contact == null) 1 else 0        is Intent.SendSms -> (if (intent.contact == null) 1 else 0) + (if (intent.message == null) 1 else 0)        is Intent.SendEmail -> (if (intent.to == null) 1 else 0) + (if (intent.subject == null) 1 else 0) + (if (intent.body == null) 1 else 0)        is Intent.OpenApp -> if (intent.appName == null && intent.packageName == null) 1 else 0        is Intent.SearchWeb -> if (intent.query == null) 1 else 0        is Intent.SetAlarm -> (if (intent.time == null) 1 else 0) + (if (intent.label == null) 1 else 0)        is Intent.SetTimer -> if (intent.duration == null) 1 else 0        is Intent.SetReminder -> (if (intent.text == null) 1 else 0) + (if (intent.time == null) 1 else 0)        is Intent.CreateNote -> if (intent.text == null) 1 else 0        is Intent.CreateCalendarEvent -> (if (intent.title == null) 1 else 0) + (if (intent.time == null) 1 else 0) + (if (intent.location == null) 1 else 0)        is Intent.Translate -> (if (intent.text == null) 1 else 0) + (if (intent.targetLanguage == null) 1 else 0)        is Intent.Compound -> intent.intents.sumOf { countNullSlots(it) }        else -> 0    }}